INSERT INTO public.periods (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic) VALUES
('d82d14ec-f97a-4529-b4d6-4a88f81d9e75','Jeunesse de Temüdjin et unification des tribus','Temüjin’s youth and the unification of the tribes','Orphelin d’un chef empoisonné, Temüdjin rassemble des fidèles et soumet une à une les tribus de la steppe ; son année de naissance est incertaine.','The orphan of a poisoned chief, Temüjin gathers followers and subdues the steppe tribes one by one; his year of birth is uncertain.',NULL,NULL,NULL,'1162','1206',864.847364818617,820.847364818617,false),
('66de0781-bece-4459-9d9d-bc86bee07052','Conquêtes de Gengis Khan','Conquests of Genghis Khan','Les armées mongoles attaquent les Xia occidentaux, la Chine des Jin puis l’Asie centrale et l’Iran.','The Mongol armies attack the Western Xia, Jin China and then Central Asia and Iran.',NULL,NULL,NULL,'1206','1227',820.847364818617,799.848049281314,false),
('dfed6378-a6ef-4768-87e0-f37be0211966','Conquête du Khwarezm','Conquest of Khwarazm','Après le massacre d’une caravane mongole, Gengis Khan détruit l’empire du Khwarezm et ses grandes villes.','After the massacre of a Mongol caravan, Genghis Khan destroys the Khwarazmian Empire and its great cities.',NULL,NULL,NULL,'1219','1221',807.848049281314,805.846680355921,false),
('25c20b40-0ddb-47e6-98b8-0a18469332c9','Enfance de Jeanne à Domrémy','Joan’s childhood at Domrémy','Fille de laboureurs aisés, Jeanne dit entendre des voix dès treize ans ; son année de naissance est approximative.','The daughter of well-off farmers, Joan says she hears voices from the age of thirteen; her year of birth is approximate.',NULL,NULL,NULL,'1412','1429-02',614.854209445585,597.767282683094,false),
('8a4ac7de-e57a-4008-b7ae-43006633354a','Campagnes de Jeanne d’Arc','Joan of Arc’s campaigns','Reçue par le dauphin à Chinon, Jeanne accompagne l’armée à Orléans, sur la Loire puis à Reims, avant d’échouer devant Paris.','Received by the dauphin at Chinon, Joan goes with the army to Orléans, the Loire and then Reims, before failing outside Paris.',NULL,NULL,NULL,'1429-02','1430-05-23',597.767282683094,596.464065708419,false),
('e4e4c811-091c-45fe-8df2-9da274b1e53f','Captivité et procès de Jeanne d’Arc','Joan of Arc’s captivity and trial','Vendue aux Anglais par les Bourguignons, Jeanne est jugée pour hérésie à Rouen par un tribunal d’Église.','Sold to the English by the Burgundians, Joan is tried for heresy at Rouen by a Church court.',NULL,NULL,NULL,'1430-05-23','1431-05-30',596.464065708419,595.445585215606,false),
('32c60c70-6d06-4520-872c-1d21f1323780','Jeunesse et vie monastique de Luther','Luther’s youth and monastic life','Fils d’un exploitant de mines, Luther entre au couvent en 1505 et enseigne la Bible à l’université de Wittenberg à partir de 1512.','The son of a mine operator, Luther enters the friary in 1505 and teaches the Bible at the University of Wittenberg from 1512.',NULL,NULL,NULL,'1483-11-10','1517-10-31',542.996577686516,509.025325119781,false),
('8dfbd53b-95d8-4fa6-ac7c-59d89eccc5ff','Rupture de Luther avec Rome','Luther’s break with Rome','Sa critique des indulgences devient une contestation de l’autorité du pape ; excommunié et mis au ban de l’Empire, Luther se cache à la Wartbourg.','His criticism of indulgences becomes a challenge to papal authority; excommunicated and outlawed in the Empire, Luther hides at the Wartburg.',NULL,NULL,NULL,'1517-10-31','1522-03',509.025325119781,504.694045174538,false),
('6d8b0cdc-e291-4b28-b81b-0dd5f50a039f','Luther organise la Réforme','Luther organises the Reformation','Revenu à Wittenberg, Luther fixe le culte, le catéchisme et le chant des nouvelles Églises, avec l’appui des princes.','Back in Wittenberg, Luther shapes the worship, catechism and hymns of the new churches, with the support of the princes.',NULL,NULL,NULL,'1522-03','1546-02-18',504.694045174538,480.724161533196,false),
('8bf78c33-6ba1-4b18-98ca-7764e2c29753','Guerre des Paysans allemands','German Peasants’ War','Des soulèvements paysans se réclament de la Réforme ; Luther les condamne et soutient la répression des princes.','Peasant uprisings invoke the Reformation; Luther condemns them and backs the princes’ repression.','Q154031','Guerre des Paysans allemands','German Peasants'' War','1524','1525',502.856947296372,501.854893908282,false),
('5216e34b-cfcc-4dd8-b744-95ccc1f23fb9','Jeunesse et navigations de Colomb','Columbus’s youth and early voyages','Fils d’un tisserand génois, Colomb navigue en Méditerranée et dans l’Atlantique puis s’établit au Portugal.','The son of a Genoese weaver, Columbus sails the Mediterranean and the Atlantic and then settles in Portugal.',NULL,NULL,NULL,'1451','1485',575.853524982888,541.852156057495,false),
('5698e277-26f5-4695-9dfb-545b77c305e2','Colomb à la recherche d’un soutien','Columbus in search of backing','Éconduit par le roi du Portugal, Colomb défend pendant sept ans son projet de route occidentale vers l’Asie devant les Rois catholiques.','Turned down by the king of Portugal, Columbus argues for seven years before the Catholic Monarchs for a western route to Asia.',NULL,NULL,NULL,'1485','1492-08-03',541.852156057495,534.265571526352,false),
('8dfb6864-3a71-4f46-bf72-e76dd7866808','Dernières années de Colomb','Columbus’s last years','Malade, Colomb réclame en vain à la Couronne les titres et les revenus promis.','In poor health, Columbus vainly claims from the Crown the titles and revenues he was promised.',NULL,NULL,NULL,'1504-11-07','1506-05-20',522.005475701574,520.475017111567,false),
('69302fb0-41ac-4137-8782-e9c166913de2','Jeunesse de Lincoln sur la Frontière','Lincoln’s youth on the frontier','Né dans une famille de pionniers pauvres, Lincoln grandit dans l’Indiana, se forme seul et s’installe dans l’Illinois.','Born into a family of poor pioneers, Lincoln grows up in Indiana, educates himself and settles in Illinois.',NULL,NULL,NULL,'1809-02-12','1834',217.745379876797,192.861054072553,false),
('13f3a388-2e69-4a55-89df-b9dd33d89a62','Lincoln avocat et élu de l’Illinois','Lincoln as Illinois lawyer and politician','Député de l’Illinois puis représentant au Congrès, Lincoln rejoint le Parti républicain et combat l’extension de l’esclavage.','A state legislator and then a congressman, Lincoln joins the Republican Party and fights the extension of slavery.',NULL,NULL,NULL,'1834','1861-03-04',192.861054072553,165.690622861054,false),
('8ef1e803-03bc-4771-8f2e-e5c614d44de2','Présidence d’Abraham Lincoln','Presidency of Abraham Lincoln','Lincoln mène l’Union pendant toute la guerre de Sécession et fait de l’abolition de l’esclavage un but de guerre.','Lincoln leads the Union throughout the Civil War and makes the abolition of slavery a war aim.',NULL,NULL,NULL,'1861-03-04','1865-04-15',165.690622861054,161.575633127995,true),
('d33e183c-d2c0-459a-9af7-ba393e5dc1fc','Jeunesse de Mao dans le Hunan','Mao’s youth in Hunan','Fils d’un paysan aisé, Mao devient instituteur à Changsha et découvre le marxisme à Pékin.','The son of a prosperous peasant, Mao becomes a schoolteacher in Changsha and discovers Marxism in Beijing.',NULL,NULL,NULL,'1893-12-26','1921-07-23',132.877481177276,105.307323750856,false),
('5691a7e9-f3cb-4822-96ec-889cece0d766','Mao révolutionnaire et chef de guérilla','Mao as revolutionary and guerrilla leader','Après la rupture avec le Guomindang, Mao organise des bases rurales et une armée de paysans dans le Jiangxi.','After the break with the Kuomintang, Mao organises rural bases and a peasant army in Jiangxi.',NULL,NULL,NULL,'1921-07-23','1935-01',105.307323750856,91.864476386037,false),
('2efd4312-b789-4084-8ef6-3a450d7a4590','Mao à la tête du Parti communiste','Mao at the head of the Communist Party','Depuis Yan’an, Mao impose sa ligne au Parti, combat le Japon puis l’emporte sur les nationalistes dans la guerre civile.','From Yan’an, Mao imposes his line on the Party, fights Japan and then defeats the Nationalists in the civil war.',NULL,NULL,NULL,'1935-01','1949-10-01',91.864476386037,77.1156741957563,false),
('1c4ac958-cdec-4d8c-8f0c-6a9a8cda206d','Jeunesse et études de Darwin','Darwin’s youth and studies','Darwin abandonne la médecine à Édimbourg, puis prépare à Cambridge une carrière de pasteur tout en se passionnant pour l’histoire naturelle.','Darwin gives up medicine at Edinburgh, then prepares at Cambridge for a career in the Church while developing a passion for natural history.',NULL,NULL,NULL,'1809-02-12','1831-12-27',217.745379876797,194.876112251882,false),
('7bf446ea-bd4a-43da-8d32-536c62aa8cb3','Voyage du Beagle','Voyage of the Beagle','Naturaliste à bord, Darwin fait le tour du monde et rassemble fossiles, roches et spécimens, surtout en Amérique du Sud.','As ship’s naturalist, Darwin sails round the world collecting fossils, rocks and specimens, above all in South America.','Q1564366','Second voyage du HMS Beagle','Second voyage of HMS Beagle','1831-12-27','1836-10-02',194.876112251882,190.109514031485,false),
('da4bfb10-4521-4068-9aaa-9d8bd8503196','Darwin élabore sa théorie','Darwin develops his theory','Installé à Down House, Darwin conçoit la sélection naturelle dès 1838 mais accumule les preuves pendant vingt ans avant de publier.','Settled at Down House, Darwin conceives natural selection as early as 1838 but gathers evidence for twenty years before publishing.',NULL,NULL,NULL,'1836-10-02','1859-11-24',190.109514031485,166.966461327858,false),
('eb8b7c18-6bb4-43bd-bf1a-f7909372fc72','Darwin après L’Origine des espèces','Darwin after the Origin of Species','Darwin étend sa théorie à l’être humain, aux émotions et aux plantes, laissant à ses partisans les controverses publiques.','Darwin extends his theory to human beings, the emotions and plants, leaving public controversy to his supporters.',NULL,NULL,NULL,'1859-11-24','1882-04-19',166.966461327858,144.565366187543,false),
('c76b0f0e-5a56-4806-95d2-c18689a87b83','Jeunesse de Marie Skłodowska en Pologne','Maria Skłodowska’s youth in Poland','Dans la Pologne sous domination russe, où l’université est fermée aux femmes, Maria travaille comme gouvernante pour financer ses études.','In Russian-ruled Poland, where the university is closed to women, Maria works as a governess to pay for her studies.',NULL,NULL,NULL,'1867-11-07','1891-11',159.013004791239,135.029431895962,false),
('5d476a61-f468-46be-bd57-b5bff33c7171','Études et recherches de Marie Curie avec Pierre','Marie Curie’s studies and research with Pierre','Licenciée en physique et en mathématiques à la Sorbonne, Marie consacre sa thèse aux rayons de l’uranium et travaille avec son mari.','With degrees in physics and mathematics from the Sorbonne, Marie devotes her thesis to uranium rays and works with her husband.',NULL,NULL,NULL,'1891-11','1906-04-19',135.029431895962,120.56810403833,false),
('f26f855b-0c05-4cd3-b84a-955191bd15fe','Marie Curie à la tête de son laboratoire','Marie Curie at the head of her laboratory','Après la mort de Pierre, Marie reprend sa chaire, isole le radium métallique et développe les usages médicaux de la radioactivité.','After Pierre’s death, Marie takes over his chair, isolates metallic radium and develops the medical uses of radioactivity.',NULL,NULL,NULL,'1906-04-19','1934-07-04',120.56810403833,92.3600273785079,false),
('efbef722-35a6-4473-8d6a-b4d6d8d3a4f5','Jeunesse et militantisme clandestin de Staline','Stalin’s youth and underground activism','Renvoyé du séminaire de Tiflis, Iossif Djougachvili devient révolutionnaire professionnel et connaît plusieurs exils en Sibérie.','Expelled from the Tiflis seminary, Ioseb Jughashvili becomes a professional revolutionary and is exiled to Siberia several times.',NULL,NULL,NULL,'1878-12-18','1917-11-07',147.90006844627,109.014373716632,false),
('59541109-d50f-4df4-aeed-24913029c7c9','Staline dans l’appareil bolchevique','Stalin in the Bolshevik apparatus','Commissaire aux Nationalités puis secrétaire général, Staline écarte un à un ses rivaux après la mort de Lénine.','People’s commissar for nationalities and then general secretary, Stalin removes his rivals one by one after Lenin’s death.',NULL,NULL,NULL,'1917-11-07','1929',109.014373716632,97.8631074606434,false),
('20f89e9d-8a97-4681-8dcc-3db20995c533','Staline maître de l’URSS','Stalin as master of the USSR','Staline impose l’industrialisation à marche forcée et la collectivisation des terres, au prix de famines et d’une répression de masse.','Stalin imposes forced industrialisation and the collectivisation of land, at the cost of famines and mass repression.',NULL,NULL,NULL,'1929','1941-06-22',97.8631074606434,85.3921971252567,false),
('a92d8fa3-d200-4428-83d4-4df161d9df99','Grandes Purges','Great Purge','Procès publics, arrestations et exécutions frappent les cadres du Parti, l’armée et des centaines de milliers de citoyens.','Show trials, arrests and executions strike Party officials, the army and hundreds of thousands of citizens.','Q187650','Grandes Purges','Great Purge','1936-08','1938-11',90.2819986310746,88.031485284052,false),
('037c838b-c8f0-4813-a9a0-f6a18f421197','Staline chef de guerre','Stalin as war leader','Surpris par l’invasion allemande, Staline dirige l’effort de guerre soviétique jusqu’à la prise de Berlin.','Caught off guard by the German invasion, Stalin directs the Soviet war effort until the capture of Berlin.',NULL,NULL,NULL,'1941-06-22','1945-05-09',85.3921971252567,81.5126625598905,false),
('e51f73c2-1ff6-42b5-aa84-58c80878c933','Dernières années de Staline','Stalin’s last years','Staline étend le modèle soviétique à l’Europe de l’Est et relance la répression à l’intérieur.','Stalin extends the Soviet model to Eastern Europe and renews repression at home.',NULL,NULL,NULL,'1945-05-09','1953-03-05',81.5126625598905,73.6906228610541,false),
('ecf1e1e5-b079-4396-8384-468adc693b1e','Jeunesse et formation de Léonard à Florence','Leonardo’s youth and training in Florence','Fils naturel d’un notaire, Léonard apprend la peinture et la sculpture dans l’atelier d’Andrea del Verrocchio.','The illegitimate son of a notary, Leonardo learns painting and sculpture in the workshop of Andrea del Verrocchio.',NULL,NULL,NULL,'1452-04-15','1482',574.566735112936,544.852840520192,false),
('156fc40a-8584-49c4-bb2a-b8f8138ae0ff','Léonard à la cour de Milan','Leonardo at the court of Milan','Au service de Ludovic Sforza, Léonard peint, organise des fêtes, étudie l’anatomie et dessine des machines.','In the service of Ludovico Sforza, Leonardo paints, stages festivities, studies anatomy and draws machines.',NULL,NULL,NULL,'1482','1499',544.852840520192,527.853524982888,false),
('0d776749-7d1c-47d8-bc2a-fc67f618c8a3','Années d’itinérance de Léonard','Leonardo’s years of travel','Chassé de Milan par l’invasion française, Léonard travaille à Venise, Florence, Milan de nouveau puis Rome.','Driven from Milan by the French invasion, Leonardo works in Venice, Florence, Milan again and then Rome.',NULL,NULL,NULL,'1499','1516',527.853524982888,510.856947296372,false),
('d082cf6d-bdf0-4196-9075-c5b4206933a7','Léonard en France','Leonardo in France','Invité par François Ier, Léonard s’installe au Clos Lucé, près d’Amboise, avec ses carnets et la Joconde.','Invited by Francis I, Leonardo settles at Clos Lucé, near Amboise, with his notebooks and the Mona Lisa.',NULL,NULL,NULL,'1516','1519-05-02',510.856947296372,507.524982888433,false),
('3ddc5cc3-d128-4f44-9336-4ca02ff08083','Jeunesse et formation de Mandela','Mandela’s youth and education','Issu de la famille royale thembu, Mandela étudie le droit et s’installe à Johannesburg.','Born into the Thembu royal family, Mandela studies law and settles in Johannesburg.',NULL,NULL,NULL,'1918-07-18','1944',108.321697467488,82.8651608487337,false),
('5391cb5b-01be-497e-8851-5ae0f316263e','Mandela militant de l’ANC','Mandela as ANC activist','Mandela anime la Ligue de jeunesse de l’ANC, organise la désobéissance civile puis, après Sharpeville, la lutte armée.','Mandela leads the ANC Youth League, organises civil disobedience and then, after Sharpeville, the armed struggle.',NULL,NULL,NULL,'1944','1962-08-05',82.8651608487337,64.2724161533196,false),
('2521b043-dd39-4ade-8f2b-54879145590b','Captivité de Mandela','Mandela’s imprisonment','Condamné à la prison à vie, Mandela passe dix-huit ans à Robben Island et devient le symbole mondial de la lutte contre l’apartheid.','Sentenced to life imprisonment, Mandela spends eighteen years on Robben Island and becomes the worldwide symbol of the struggle against apartheid.',NULL,NULL,NULL,'1962-08-05','1990-02-11',64.2724161533196,36.7515400410678,false),
('e586fa24-8216-4746-8927-e92155b0fc74','Mandela négocie la fin de l’apartheid','Mandela negotiates the end of apartheid','Libéré, Mandela négocie avec le président Frederik de Klerk une nouvelle Constitution et des élections ouvertes à tous.','Once freed, Mandela negotiates with President F. W. de Klerk a new constitution and elections open to all.',NULL,NULL,NULL,'1990-02-11','1994-05-10',36.7515400410678,32.5106091718001,false),
('75b0d6ef-5a9d-4cf0-bacc-1dc4acf53749','Présidence de Nelson Mandela','Presidency of Nelson Mandela','Mandela dirige un gouvernement d’union nationale et met en place la Commission de la vérité et de la réconciliation.','Mandela leads a government of national unity and sets up the Truth and Reconciliation Commission.',NULL,NULL,NULL,'1994-05-10','1999-06-14',32.5106091718001,27.4154688569473,true),
('97a96018-fe67-4989-a425-5ae48c5936d2','Retraite de Mandela','Mandela’s retirement','Mandela se consacre à sa fondation, à la lutte contre le sida et à des médiations en Afrique.','Mandela devotes himself to his foundation, the fight against AIDS and mediation in Africa.',NULL,NULL,NULL,'1999-06-14','2013-12-05',27.4154688569473,12.9377138945927,false),
('cfa16e29-b327-44f8-a72f-4b71d053206f','Apartheid','Apartheid','Le régime sud-africain classe la population par race et réserve à la minorité blanche le pouvoir, les terres et les meilleurs emplois.','The South African regime classifies the population by race and reserves power, land and the best jobs for the white minority.','Q11409','Apartheid','Apartheid','1948','1994-04-27',78.8651608487337,32.5462012320329,false);
INSERT INTO public.events (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,date,date_years_bp) VALUES
('4b45314f-104c-41b8-94df-884cd1c19e2b','Naissance de Temüdjin','Birth of Temüjin','Le futur Gengis Khan naît près du fleuve Onon ; les sources hésitent entre 1155, 1162 et 1167.','The future Genghis Khan is born near the Onon river; the sources hesitate between 1155, 1162 and 1167.',NULL,NULL,NULL,'1162',864.847364818617),
('1521509b-6ac9-4aca-b212-0882fca936ba','Prise de Samarcande','Fall of Samarkand','La capitale du Khwarezm se rend après quelques jours de siège ; sa garnison est massacrée.','The Khwarazmian capital surrenders after a few days of siege; its garrison is massacred.',NULL,NULL,NULL,'1220',806.848733744011),
('740c164f-c0e0-4f30-809b-b47bce203fa4','Mort de Gengis Khan','Death of Genghis Khan','Gengis Khan meurt pendant la campagne contre les Xia occidentaux ; son fils Ögödei lui succède.','Genghis Khan dies during the campaign against the Western Xia; his son Ögedei succeeds him.',NULL,NULL,NULL,'1227',799.848049281314),
('4d57a530-3d9a-4e85-b014-9437d0912e71','Naissance de Jeanne d’Arc','Birth of Joan of Arc','Jeanne naît à Domrémy, village de la vallée de la Meuse resté fidèle au dauphin.','Joan is born at Domrémy, a village in the Meuse valley that remained loyal to the dauphin.',NULL,NULL,NULL,'1412',614.854209445585),
('40ec62f6-0696-4130-bbed-60c8000a233e','Jeanne d’Arc rencontre le dauphin à Chinon','Joan of Arc meets the dauphin at Chinon','Le futur Charles VII la fait examiner par des théologiens à Poitiers avant de lui confier un convoi pour Orléans.','The future Charles VII has her examined by theologians at Poitiers before entrusting her with a convoy for Orléans.',NULL,NULL,NULL,'1429-03',597.690622861054),
('da8b70fe-5870-4e97-b32c-f52f49a0dfb7','Bataille de Patay','Battle of Patay','La cavalerie française surprend et détruit l’armée anglaise de la Loire.','The French cavalry surprises and destroys the English army of the Loire.','Q648535','Bataille de Patay','Battle of Patay','1429-06-18',597.392197125257),
('981580d2-2b0f-4253-8b9c-117497f08efd','Échec de Jeanne d’Arc devant Paris','Joan of Arc’s failure before Paris','Blessée à la porte Saint-Honoré, Jeanne doit renoncer à prendre la ville tenue par les Bourguignons.','Wounded at the Saint-Honoré gate, Joan has to give up taking the city held by the Burgundians.',NULL,NULL,NULL,'1429-09-08',597.167693360712),
('d90f2c0f-61a3-4617-b901-a7625b2325d9','Capture de Jeanne d’Arc à Compiègne','Capture of Joan of Arc at Compiègne','Lors d’une sortie, Jeanne est faite prisonnière par les hommes de Jean de Luxembourg.','During a sortie, Joan is taken prisoner by the men of John of Luxembourg.','Q668577','Siège de Compiègne','Siege of Compiègne','1430-05-23',596.464065708419),
('f32a9997-f8de-4840-8e49-c642dcb5b9b2','Réhabilitation de Jeanne d’Arc','Rehabilitation of Joan of Arc','Un second procès, voulu par Charles VII, annule la condamnation de 1431.','A second trial, sought by Charles VII, annuls the sentence of 1431.',NULL,NULL,NULL,'1456-07-07',570.339493497604),
('f7864a07-295b-4993-b32d-df1c3a2daedc','Naissance de Martin Luther','Birth of Martin Luther','Luther naît à Eisleben, en Saxe, et est baptisé le lendemain, jour de la Saint-Martin.','Luther is born at Eisleben in Saxony and baptised the next day, the feast of St Martin.',NULL,NULL,NULL,'1483-11-10',542.996577686516),
('86a07a5c-9e00-4681-a12a-be260fb3e3b7','Excommunication de Luther','Excommunication of Luther','Le pape Léon X l’excommunie après que Luther a brûlé publiquement la bulle qui le menaçait.','Pope Leo X excommunicates him after Luther publicly burned the bull that threatened him.',NULL,NULL,NULL,'1521-01-03',505.849418206708),
('23c1c4ff-2bc4-418d-9710-61037977ae5d','Luther devant la diète de Worms','Luther before the Diet of Worms','Devant Charles Quint, Luther refuse de se rétracter ; l’empereur le met au ban de l’Empire.','Before Charles V, Luther refuses to recant; the emperor places him under the imperial ban.',NULL,NULL,NULL,'1521-04-18',505.561943874059),
('ccc6b9d5-ab5b-49a1-bfb0-38b591c138a5','Mariage de Luther et de Katharina von Bora','Marriage of Luther and Katharina von Bora','L’ancien moine épouse une ancienne religieuse, donnant l’exemple du mariage des pasteurs.','The former friar marries a former nun, setting the example of married clergy.',NULL,NULL,NULL,'1525-06-13',501.408624229979),
('a23d322b-e19d-405a-a05a-659c6b1486e6','Confession d’Augsbourg','Augsburg Confession','Rédigée par Melanchthon, la profession de foi des luthériens est présentée à Charles Quint.','Drafted by Melanchthon, the Lutheran confession of faith is presented to Charles V.','Q154483','Confession d''Augsbourg','Augsburg Confession','1530-06-25',496.376454483231),
('bfccb09c-d368-40e9-9f99-60e4b423c0f3','Bible de Luther','Luther Bible','Douze ans après le Nouveau Testament, Luther publie la Bible entière en allemand ; sa langue marque durablement l’allemand écrit.','Twelve years after the New Testament, Luther publishes the whole Bible in German; its language leaves a lasting mark on written German.','Q1571095','Bible de Luther','Luther Bible','1534',492.855578370979),
('4f089db1-167e-49e6-9fb8-55cefb105177','Mort de Martin Luther','Death of Martin Luther','Luther meurt à Eisleben, sa ville natale, et est inhumé dans l’église du château de Wittenberg.','Luther dies at Eisleben, his birthplace, and is buried in the castle church at Wittenberg.',NULL,NULL,NULL,'1546-02-18',480.724161533196),
('1aa62042-af41-4077-90b9-612e1f3a85d7','Naissance de Christophe Colomb','Birth of Christopher Columbus','Colomb naît à Gênes ; la date exacte n’est pas connue.','Columbus is born in Genoa; the exact date is unknown.',NULL,NULL,NULL,'1451',575.853524982888),
('3eb9f317-0f59-49e6-91b8-4ba0dcf10790','Capitulations de Santa Fe','Capitulations of Santa Fe','Les Rois catholiques lui promettent les titres d’amiral et de vice-roi et un dixième des richesses à découvrir.','The Catholic Monarchs promise him the titles of admiral and viceroy and a tenth of the riches to be found.','Q1728627','Capitulations de Santa Fe','Capitulations of Santa Fe','1492-04-17',534.561259411362),
('b34d306c-e2eb-4855-9292-b6c7bc09099e','Retour de Colomb en Espagne','Columbus returns to Spain','Colomb rentre à Palos et annonce avoir atteint les Indes par l’ouest.','Columbus returns to Palos and announces that he has reached the Indies by sailing west.',NULL,NULL,NULL,'1493-03-15',533.652292950034),
('92849ab3-d7cc-4165-8153-a4d7d23c9dd0','Colomb arrêté à Hispaniola','Columbus arrested on Hispaniola','Accusé de mauvais gouvernement, Colomb est renvoyé enchaîné en Espagne par l’enquêteur Francisco de Bobadilla.','Accused of misrule, Columbus is sent back to Spain in chains by the investigator Francisco de Bobadilla.',NULL,NULL,NULL,'1500-08',526.273785078713),
('255c4236-5ed5-441b-b97c-28d455a10770','Mort de Christophe Colomb','Death of Christopher Columbus','Colomb meurt à Valladolid, convaincu d’avoir atteint les abords de l’Asie.','Columbus dies at Valladolid, convinced that he reached the approaches to Asia.',NULL,NULL,NULL,'1506-05-20',520.475017111567),
('523907c2-8d18-42ae-8253-36e487c39ad1','Naissance d’Abraham Lincoln','Birth of Abraham Lincoln','Lincoln naît dans une cabane en rondins près de Hodgenville, dans le Kentucky.','Lincoln is born in a log cabin near Hodgenville, Kentucky.',NULL,NULL,NULL,'1809-02-12',217.745379876797),
('b58c84a3-fd64-4b69-ab5c-786f664cccce','Débats Lincoln-Douglas','Lincoln–Douglas debates','Candidat au Sénat, Lincoln affronte Stephen Douglas sur l’esclavage dans sept débats qui le font connaître du pays.','Running for the Senate, Lincoln confronts Stephen Douglas over slavery in seven debates that make him known nationwide.','Q622354','Débats Lincoln-Douglas','Lincoln–Douglas debates','1858-08-21',168.225872689938),
('70809365-87a9-469f-9edb-c2b58303f153','Élection d’Abraham Lincoln','Election of Abraham Lincoln','La victoire du candidat républicain entraîne la sécession de sept États du Sud avant même son investiture.','The Republican candidate’s victory leads seven Southern states to secede even before his inauguration.','Q698842','Élection présidentielle américaine de 1860','1860 United States presidential election','1860-11-06',166.013689253936),
('86344162-d418-478c-87d1-d6c6a1ac1a26','Discours de Gettysburg','Gettysburg Address','En deux minutes, Lincoln définit la guerre comme un combat pour l’égalité et le gouvernement du peuple.','In two minutes, Lincoln defines the war as a struggle for equality and government of the people.','Q214524','Discours de Gettysburg','Gettysburg Address','1863-11-19',162.980150581793),
('0db81758-6fd2-416c-9587-26d502f81ac1','Réélection d’Abraham Lincoln','Re-election of Abraham Lincoln','Lincoln bat le général McClellan, partisan d’une paix négociée avec le Sud.','Lincoln defeats General McClellan, who favoured a negotiated peace with the South.',NULL,NULL,NULL,'1864-11-08',162.008213552361),
('50e2cb31-3dd6-452e-80d3-bef798e72d61','Naissance de Mao Zedong','Birth of Mao Zedong','Mao naît à Shaoshan, village du Hunan.','Mao is born in Shaoshan, a village in Hunan.',NULL,NULL,NULL,'1893-12-26',132.877481177276),
('e22017ad-5c40-4c79-9982-5cb86e4c4d25','Conférence de Zunyi','Zunyi Conference','Pendant la Longue Marche, la direction du Parti est remaniée et Mao entre dans le groupe qui commande l’armée.','During the Long March, the Party leadership is reshuffled and Mao joins the group commanding the army.','Q30341',NULL,'Zunyi Conference','1935-01',91.864476386037),
('0de46990-44e4-4851-b9c6-e2320f9684a6','Campagne des Cent Fleurs','Hundred Flowers Campaign','Mao invite les intellectuels à critiquer le régime ; l’année suivante, une campagne « antidroitiers » frappe ceux qui ont parlé.','Mao invites intellectuals to criticise the regime; the following year an “anti-rightist” campaign strikes those who spoke out.','Q517371','Campagne des Cent Fleurs','Hundred Flowers Campaign','1956-05',70.5338809034908),
('03e01717-e3af-4893-81cb-47084cb74341','Naissance de Charles Darwin','Birth of Charles Darwin','Darwin naît à Shrewsbury dans une famille de médecins et d’industriels.','Darwin is born in Shrewsbury into a family of physicians and industrialists.',NULL,NULL,NULL,'1809-02-12',217.745379876797),
('3a85a8ce-5e7e-49e8-a8c4-988f1acc54b4','Darwin aux îles Galápagos','Darwin in the Galápagos Islands','Pendant cinq semaines, Darwin observe des espèces qui diffèrent d’une île à l’autre.','For five weeks Darwin observes species that differ from one island to the next.',NULL,NULL,NULL,'1835-09',191.196440793977),
('e6070b70-d6e7-4515-a8a9-678de4c7dd96','Darwin et Wallace présentés à la Société linnéenne','Darwin and Wallace read at the Linnean Society','Alfred Russel Wallace étant parvenu à la même idée, leurs textes sur la sélection naturelle sont lus ensemble à Londres.','Alfred Russel Wallace having reached the same idea, their papers on natural selection are read together in London.',NULL,NULL,NULL,'1858-07-01',168.365503080082),
('1fb4eb02-8661-4c5b-93d3-e17cf1907671','Débat d’Oxford sur l’évolution','Oxford evolution debate','Thomas Huxley défend la théorie de Darwin face à l’évêque Samuel Wilberforce.','Thomas Huxley defends Darwin’s theory against Bishop Samuel Wilberforce.',NULL,NULL,NULL,'1860-06-30',166.366872005476),
('cf458d1b-d1a2-427e-b312-41b33a23eda1','La Filiation de l’homme','The Descent of Man','Darwin applique l’évolution à l’espèce humaine et expose la sélection sexuelle.','Darwin applies evolution to the human species and sets out sexual selection.','Q1165434','La Filiation de l''homme et la sélection liée au sexe','The Descent of Man, and Selection in Relation to Sex','1871-02-24',155.713894592745),
('088647a2-4d24-4a70-aac0-37a2997adebc','Mort de Charles Darwin','Death of Charles Darwin','Darwin meurt à Down House et est inhumé à l’abbaye de Westminster, près de Newton.','Darwin dies at Down House and is buried in Westminster Abbey, near Newton.',NULL,NULL,NULL,'1882-04-19',144.565366187543),
('e8d4a8a8-a970-4be4-a6d6-e5c04e69d664','Naissance de Marie Skłodowska','Birth of Maria Skłodowska','Maria Skłodowska naît à Varsovie dans une famille d’enseignants.','Maria Skłodowska is born in Warsaw into a family of teachers.',NULL,NULL,NULL,'1867-11-07',159.013004791239),
('4bef8209-7f70-4271-b1f6-9dde47bd727d','Mariage de Marie et Pierre Curie','Marriage of Marie and Pierre Curie','Marie épouse à Sceaux le physicien Pierre Curie, spécialiste du magnétisme et des cristaux.','At Sceaux, Marie marries the physicist Pierre Curie, a specialist in magnetism and crystals.',NULL,NULL,NULL,'1895-07-26',131.297741273101),
('308995e9-da6d-4a3e-8858-685ba22f2881','Découverte du polonium','Discovery of polonium','Les Curie annoncent un nouvel élément, nommé d’après la Pologne, et emploient pour la première fois le mot « radioactif ».','The Curies announce a new element, named after Poland, and use the word “radioactive” for the first time.',NULL,NULL,NULL,'1898-07',128.365503080082),
('b3a37e7c-74e2-459c-9bb0-d2405a28216c','Prix Nobel de physique des Curie et de Becquerel','Nobel Prize in Physics for the Curies and Becquerel','Marie Curie est la première femme à recevoir un prix Nobel, partagé avec Pierre Curie et Henri Becquerel.','Marie Curie is the first woman to receive a Nobel Prize, shared with Pierre Curie and Henri Becquerel.',NULL,NULL,NULL,'1903-12-10',122.925393566051),
('45f7949c-3f68-46bd-977b-3800e06c6d5c','Marie Curie première professeure à la Sorbonne','Marie Curie first woman professor at the Sorbonne','Marie Curie donne son premier cours dans la chaire de son mari, mort quelques mois plus tôt dans un accident.','Marie Curie gives her first lecture in the chair of her husband, killed in an accident a few months earlier.',NULL,NULL,NULL,'1906-11-05',120.020533880903),
('1789ef56-72a9-4435-9402-174049e5baa2','Prix Nobel de chimie de Marie Curie','Marie Curie’s Nobel Prize in Chemistry','Récompensée pour le polonium et le radium, Marie Curie devient la première personne à recevoir deux prix Nobel.','Honoured for polonium and radium, Marie Curie becomes the first person to receive two Nobel Prizes.',NULL,NULL,NULL,'1911-12-10',114.925393566051),
('f6a39d5c-698e-4ef4-99f3-c595f3cc8678','Marie Curie équipe des voitures radiologiques','Marie Curie equips mobile X-ray units','Pendant la Grande Guerre, Marie Curie organise des voitures de radiologie, les « petites Curies », pour examiner les blessés près du front.','During the Great War, Marie Curie organises X-ray cars, the “petites Curies”, to examine the wounded near the front.',NULL,NULL,NULL,'1914',112.86379192334),
('428cd37a-8ca2-4456-bc5e-8b118f8072f1','Mort de Marie Curie','Death of Marie Curie','Marie Curie meurt d’une anémie due à son exposition prolongée aux rayonnements.','Marie Curie dies of an anaemia caused by her long exposure to radiation.',NULL,NULL,NULL,'1934-07-04',92.3600273785079),
('e03e7663-e1d7-4ee7-8be9-e9765be269f2','Naissance de Staline','Birth of Stalin','Staline naît à Gori, en Géorgie, fils d’un cordonnier ; il donnera plus tard 1879 comme année de naissance.','Stalin is born in Gori, Georgia, the son of a cobbler; he will later give 1879 as his year of birth.',NULL,NULL,NULL,'1878-12-18',147.90006844627),
('613e6795-853e-416c-9bc8-6aa40f73d5ad','Staline secrétaire général du Parti','Stalin becomes general secretary of the Party','Ce poste d’organisation, jugé secondaire, lui donne la main sur les nominations dans tout l’appareil.','This organisational post, thought minor, gives him control over appointments throughout the apparatus.',NULL,NULL,NULL,'1922-04-03',104.611909650924),
('497802e7-6f22-4b7b-b984-0052f4401fe9','Testament de Lénine','Lenin’s Testament','Malade, Lénine dicte des notes qui jugent Staline trop brutal et proposent de l’écarter du secrétariat général.','Ailing, Lenin dictates notes that judge Stalin too rough and propose removing him as general secretary.','Q2375101','Testament de Lénine','Lenin''s Testament','1922-12',103.949349760438),
('06abc967-3b61-45da-88aa-460e0b881fb4','Premier plan quinquennal','First five-year plan','Le plan fixe des objectifs très élevés à l’industrie lourde et met fin à la Nouvelle politique économique.','The plan sets very high targets for heavy industry and ends the New Economic Policy.','Q1661958',NULL,'First five-year plan (Soviet Union)','1928-10-01',98.1149897330595),
('88af82b6-d3e8-4016-bb53-7004f80fdd05','Collectivisation des terres en URSS','Collectivisation of land in the USSR','Les paysans sont contraints d’entrer dans des fermes collectives ; les récalcitrants, dits koulaks, sont déportés.','Peasants are forced into collective farms; those who resist, labelled kulaks, are deported.','Q821122','Collectivisation en Union soviétique','Collectivization in the Soviet Union','1929',97.8631074606434),
('ae788302-2216-4892-bd65-f4d1d4298123','Mort de Staline','Death of Stalin','Staline meurt dans sa datcha de Kountsevo, quatre jours après une attaque cérébrale.','Stalin dies at his Kuntsevo dacha, four days after a stroke.',NULL,NULL,NULL,'1953-03-05',73.6906228610541),
('e70ffc6c-8ba2-4a11-a09e-a0cfee9eabbd','Naissance de Léonard de Vinci','Birth of Leonardo da Vinci','Léonard naît à Vinci, bourg toscan proche de Florence.','Leonardo is born at Vinci, a Tuscan village near Florence.',NULL,NULL,NULL,'1452-04-15',574.566735112936),
('b9ce49c9-ebf6-4edd-82b1-5e94c16b2e21','L’Homme de Vitruve','Vitruvian Man','Léonard dessine les proportions du corps humain inscrit dans un cercle et un carré, d’après l’architecte romain Vitruve.','Leonardo draws the proportions of the human body set in a circle and a square, after the Roman architect Vitruvius.','Q215486','Homme de Vitruve','Vitruvian Man','1490',536.852840520192),
('10c5eedc-02e5-46d9-bf97-6117e5b9a51e','La Cène de Léonard de Vinci','Leonardo’s Last Supper','Léonard achève la peinture murale du réfectoire de Santa Maria delle Grazie, à Milan.','Leonardo completes the mural in the refectory of Santa Maria delle Grazie in Milan.','Q128910','La Cène (Léonard de Vinci)','The Last Supper (Leonardo)','1498',528.852840520192),
('8bf2a85b-8e03-4b4c-a36d-9b065c0a3540','Mort de Léonard de Vinci','Death of Leonardo da Vinci','Léonard meurt au Clos Lucé et lègue ses manuscrits à son élève Francesco Melzi.','Leonardo dies at Clos Lucé and leaves his manuscripts to his pupil Francesco Melzi.',NULL,NULL,NULL,'1519-05-02',507.524982888433),
('985573f7-5627-4ce0-a490-fcca17140a40','Naissance de Nelson Mandela','Birth of Nelson Mandela','Rolihlahla Mandela naît à Mvezo, dans le Transkei.','Rolihlahla Mandela is born at Mvezo, in the Transkei.',NULL,NULL,NULL,'1918-07-18',108.321697467488),
('8f7ac21c-7075-4bfe-aadf-4a53e1bc1bea','Massacre de Sharpeville','Sharpeville massacre','La police tire sur une manifestation contre les laissez-passer et tue soixante-neuf personnes ; l’ANC est interdit peu après.','Police fire on a demonstration against the pass laws, killing sixty-nine people; the ANC is banned soon afterwards.','Q518753','Massacre de Sharpeville','Sharpeville massacre','1960-03-21',66.6461327857632),
('2ac633b0-4b9a-4538-93b9-faa79c35123a','Verdict du procès de Rivonia','Verdict of the Rivonia Trial','Mandela et sept coaccusés sont condamnés à la prison à vie pour sabotage.','Mandela and seven co-defendants are sentenced to life imprisonment for sabotage.','Q1639868','Procès de Rivonia','Rivonia Trial','1964-06-12',62.4188911704312),
('03d0912c-1128-4fd7-8bc4-82a6f7d5267e','Libération de Nelson Mandela','Release of Nelson Mandela','Après vingt-sept ans de détention, Mandela sort libre de la prison Victor Verster.','After twenty-seven years in detention, Mandela walks free from Victor Verster Prison.',NULL,NULL,NULL,'1990-02-11',36.7515400410678),
('7f4ad293-aa2a-4737-bd67-8e7da7826283','Prix Nobel de la paix de Mandela et de Klerk','Nobel Peace Prize for Mandela and de Klerk','Le prix récompense leur travail commun pour mettre fin pacifiquement à l’apartheid.','The prize rewards their joint work to end apartheid peacefully.',NULL,NULL,NULL,'1993-12-10',32.9240246406571),
('9e4fe65e-f696-48cd-969f-9f955d4b7e6b','Premières élections multiraciales en Afrique du Sud','First multiracial elections in South Africa','L’ANC l’emporte largement ; le Parlement élit Mandela président.','The ANC wins by a wide margin; Parliament elects Mandela president.','Q957012','Élections générales sud-africaines de 1994','1994 South African general election','1994-04-27',32.5462012320329),
('c79911f5-f88f-432a-93ab-1f6ac25b9737','Mort de Nelson Mandela','Death of Nelson Mandela','Mandela meurt à Johannesburg à quatre-vingt-quinze ans.','Mandela dies in Johannesburg aged ninety-five.',NULL,NULL,NULL,'2013-12-05',12.9377138945927);
